import{_ as t,a,o as d,a4 as s}from"./chunks/framework.-FZumj2l.js";const m=JSON.parse('{"title":"Addresses","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/admin/customers/addresses/index.md","filePath":"api/rest-api/admin/customers/addresses/index.md","lastUpdated":1783079210000}'),r={name:"api/rest-api/admin/customers/addresses/index.md"};function o(n,e,i,c,h,l){return d(),a("div",null,e[0]||(e[0]=[s('<h1 id="addresses" tabindex="-1">Addresses <a class="header-anchor" href="#addresses" aria-label="Permalink to &quot;Addresses&quot;">​</a></h1><p>The Addresses menu manages a customer&#39;s address book — the billing and shipping addresses saved against their account. It mirrors the address section of the admin customer screen, and the addresses here are what an admin picks from when placing an order on the customer&#39;s behalf.</p><h2 id="what-an-address-holds" tabindex="-1">What an address holds <a class="header-anchor" href="#what-an-address-holds" aria-label="Permalink to &quot;What an address holds&quot;">​</a></h2><p>An address carries the recipient&#39;s name, company, the street/city/state/country/postcode, and a phone number. One address per customer can be marked the <strong>default</strong>; that one is pre-selected at checkout and in the admin Create-Order flow.</p><h2 id="default-address-semantics" tabindex="-1">Default-address semantics <a class="header-anchor" href="#default-address-semantics" aria-label="Permalink to &quot;Default-address semantics&quot;">​</a></h2><p>A customer has at most one default address. When you create or update an address with the default flag set, the previously-default address is automatically un-flagged — there is never more than one default. The dedicated <strong>Set as Default</strong> endpoint flips an existing address to default and clears the flag on all the customer&#39;s other addresses.</p><h2 id="ownership-guard" tabindex="-1">Ownership guard <a class="header-anchor" href="#ownership-guard" aria-label="Permalink to &quot;Ownership guard&quot;">​</a></h2><p>Every address belongs to exactly one customer. Address endpoints are nested under that customer (<code>/customers/{customerId}/addresses/...</code>), and an address whose owner doesn&#39;t match the <code>customerId</code> in the path is rejected with a <code>403</code> — one customer&#39;s addresses can never be read or modified through another customer.</p><h2 id="what-create-update-delete-do" tabindex="-1">What create / update / delete do <a class="header-anchor" href="#what-create-update-delete-do" aria-label="Permalink to &quot;What create / update / delete do&quot;">​</a></h2><ul><li><strong>Create</strong> (<code>POST</code>) adds an address to the customer&#39;s book. Setting the default flag promotes it (and demotes the old default).</li><li><strong>Update</strong> (<code>PUT</code>) edits an address; it is partial. Editing across customers is blocked by the ownership guard.</li><li><strong>Set as Default</strong> (<code>POST</code>) marks an address as the customer&#39;s default.</li><li><strong>Delete</strong> (<code>DELETE</code>) removes an address from the book.</li></ul><h2 id="endpoints-in-this-menu" tabindex="-1">Endpoints in this menu <a class="header-anchor" href="#endpoints-in-this-menu" aria-label="Permalink to &quot;Endpoints in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="./../addresses.html">List Addresses</a></td><td><code>GET /api/admin/customers/{customerId}/addresses</code></td></tr><tr><td><a href="./detail.html">Address Detail</a></td><td><code>GET /api/admin/customers/{customerId}/addresses/{id}</code></td></tr><tr><td><a href="./create.html">Create Address</a></td><td><code>POST /api/admin/customers/{customerId}/addresses</code></td></tr><tr><td><a href="./update.html">Update Address</a></td><td><code>PUT /api/admin/customers/{customerId}/addresses/{id}</code></td></tr><tr><td><a href="./delete.html">Delete Address</a></td><td><code>DELETE /api/admin/customers/{customerId}/addresses/{id}</code></td></tr><tr><td><a href="./set-default.html">Set as Default</a></td><td><code>POST /api/admin/customers/{customerId}/addresses/{id}/set-default</code></td></tr></tbody></table><p>Permissions: <code>customers.addresses.create</code> / <code>.edit</code> / <code>.delete</code>.</p><p>All endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',14)]))}const p=t(r,[["render",o]]);export{m as __pageData,p as default};
